    const transformMethods = [
      'toFixed', 'toString', 'toLowerCase', 'toUpperCase',
      'trim', 'trimStart', 'trimEnd'
    ];

    if (!transformMethods.includes(methodName)) {
      return null; // Unsupported method - mark as complex
    }

